-- 0127 — THE SIX DISHES THE EVENT PLAN COULD NOT BUY FOR.
--
-- The first production plan built against the live 9/26 booking could only put one dish on the
-- purchase list. Six of the seven had no recipe anywhere in the HUB — congrí, tamales, yuca,
-- croquetas, macaroni salad, skewers — so the plan refused to guess their ingredients and said so.
-- Añejo has sold these dishes for months; the kitchen simply knew them and the HUB did not.
--
-- These six close that gap. Each is written to a basis of 45 of its own unit, the same basis the
-- adult day care recipes use and the same one scaleQty() scales from, and each carries the portion
-- Añejo already quotes: congrí 2 cooked cups, tamales 3 slices, croquetas 1.20 oz fried, macaroni
-- salad 6 oz, skewers 1 piece. Bilingual throughout, because the cook reads Spanish.
--
-- THEY ARE SEEDED AS DRAFTS ON PURPOSE. They are written from standard Cuban practice and Añejo's
-- own stated portions, NOT transcribed from the kitchen's own way of making them. The plan labels
-- a draft a draft wherever it appears. The cook is the authority on these dishes: she corrects the
-- amounts against what she actually does, and publishing them is her call, not this file's.
--
-- Additive, INSERT OR IGNORE, no program_key — these are catering recipes and the adult day care
-- cycle does not point at them.
-- Apply: wrangler d1 execute anejo --remote --file=migrations/0127_catering_recipes.sql

INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es) VALUES ('rcp_cat_congri', 'Congrí', 'Rice and black beans cooked together in the bean liquid, the way it is served at an event. Written for 45 portions of 2 cooked cups.', '[{"item": "Long grain white rice", "qty": "12 lb (about 27 cups dry)"}, {"item": "Dry black beans", "qty": "4 lb"}, {"item": "Slab bacon or salt pork, small dice", "qty": "1½ lb"}, {"item": "Yellow onion, small dice", "qty": "2 lb"}, {"item": "Green bell pepper, small dice", "qty": "1½ lb"}, {"item": "Garlic, minced", "qty": "¾ cup"}, {"item": "Olive oil", "qty": "¾ cup"}, {"item": "Ground cumin", "qty": "3 tbsp"}, {"item": "Dried oregano", "qty": "3 tbsp"}, {"item": "Bay leaves", "qty": "6"}, {"item": "Dry white wine", "qty": "1½ cups"}, {"item": "Bean liquid plus water", "qty": "3 gal"}, {"item": "Salt", "qty": "3 tbsp"}, {"item": "Black pepper", "qty": "2 tbsp"}]', '["Soak the beans overnight in cold water. Drain, cover with fresh water and simmer 1 to 1½ hours until tender but whole. KEEP THE COOKING LIQUID — it is what makes congrí black.", "Render the bacon in a large rondeau over medium heat until the fat runs and the pieces colour.", "Add the oil, onion and pepper. Cook 8 to 10 minutes until soft, not browned. Add the garlic, cumin, oregano and bay; cook 1 minute.", "Add the wine and let it cook off, about 2 minutes.", "Rinse the rice once and stir it into the sofrito so every grain is coated.", "Measure the bean liquid and top it up with water to 3 gallons. Add it with the beans, the salt and the pepper. Taste the liquid now — it should be slightly saltier than you want the finished rice.", "Bring to a boil, stir once, then cover and drop to low. Cook 20 to 25 minutes without lifting the lid.", "Rest covered 10 minutes off the heat. Fluff with a fork, pull the bay leaves, and hold at 135°F or above."]', '["catering", "cuban", "needs_kitchen_review"]', 'draft', 1790078400000, 1790078400000, 'Congrí', 'Arroz y frijoles negros cocinados juntos en el caldo de los frijoles, como se sirve en un evento. Escrita para 45 porciones de 2 tazas cocidas.', '[{"item": "Arroz blanco de grano largo", "qty": "12 lb (unas 27 tazas crudas)"}, {"item": "Frijoles negros secos", "qty": "4 lb"}, {"item": "Tocino de lomo o tocineta en cubitos", "qty": "1½ lb"}, {"item": "Cebolla amarilla en cubitos", "qty": "2 lb"}, {"item": "Ají verde en cubitos", "qty": "1½ lb"}, {"item": "Ajo picado", "qty": "¾ taza"}, {"item": "Aceite de oliva", "qty": "¾ taza"}, {"item": "Comino molido", "qty": "3 cdas"}, {"item": "Orégano seco", "qty": "3 cdas"}, {"item": "Hojas de laurel", "qty": "6"}, {"item": "Vino blanco seco", "qty": "1½ tazas"}, {"item": "Caldo de los frijoles con agua", "qty": "3 galones"}, {"item": "Sal", "qty": "3 cdas"}, {"item": "Pimienta negra", "qty": "2 cdas"}]', '["Remoje los frijoles toda la noche en agua fría. Escurra, cubra con agua limpia y hierva a fuego lento de 1 a 1½ horas hasta que estén tiernos pero enteros. GUARDE EL CALDO — es lo que hace negro al congrí.", "Sofría la tocineta en una olla ancha a fuego medio hasta que suelte la grasa y dore.", "Agregue el aceite, la cebolla y el ají. Cocine de 8 a 10 minutos hasta ablandar, sin dorar. Agregue el ajo, el comino, el orégano y el laurel; cocine 1 minuto.", "Agregue el vino y deje que se evapore, unos 2 minutos.", "Enjuague el arroz una vez y revuélvalo en el sofrito hasta que cada grano quede cubierto.", "Mida el caldo de los frijoles y complete con agua hasta 3 galones. Agréguelo con los frijoles, la sal y la pimienta. Pruebe el líquido ahora — debe quedar un poco más salado que como quiere el arroz terminado.", "Lleve a hervor, revuelva una vez, tape y baje a fuego lento. Cocine de 20 a 25 minutos sin destapar.", "Repose tapado 10 minutos fuera del fuego. Suelte con tenedor, retire el laurel y mantenga a 135°F o más."]', '45 portions of 2 cooked cups', '45 porciones de 2 tazas cocidas');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es) VALUES ('rcp_cat_tamales', 'Cuban tamales', 'Corn masa with pork, tied in husks and boiled. Written for 45 tamales, which is 45 portions of 3 slices.', '[{"item": "Masa harina for tamales (or 14 lb fresh ground corn)", "qty": "10 lb"}, {"item": "Pork shoulder, small dice", "qty": "6 lb"}, {"item": "Slab bacon, small dice", "qty": "1 lb"}, {"item": "Yellow onion, small dice", "qty": "2 lb"}, {"item": "Green bell pepper, small dice", "qty": "1½ lb"}, {"item": "Garlic, minced", "qty": "½ cup"}, {"item": "Tomato sauce", "qty": "1 qt"}, {"item": "Ground cumin", "qty": "2 tbsp"}, {"item": "Dried oregano", "qty": "2 tbsp"}, {"item": "Sweet paprika", "qty": "2 tbsp"}, {"item": "Dry white wine", "qty": "1 cup"}, {"item": "Pork stock or water, warm", "qty": "2½ gal"}, {"item": "Salt", "qty": "3 tbsp"}, {"item": "Black pepper", "qty": "1 tbsp"}, {"item": "Dried corn husks", "qty": "100 (allow for breakage)"}, {"item": "Butcher twine", "qty": "1 roll"}]', '["Soak the husks in hot water at least 30 minutes, until they are soft enough to fold without cracking.", "Render the bacon, then brown the pork in the fat in batches. Do not crowd the pan.", "Add the onion and pepper; cook until soft. Add the garlic, cumin, oregano and paprika; cook 1 minute. Add the wine, then the tomato sauce. Simmer 15 minutes. Set half of this aside as the filling.", "Whisk the masa harina into the warm stock until it is smooth and pourable — about the thickness of pancake batter. Stir in the remaining sofrito, the salt and the pepper.", "Lay two husks overlapping. Put a generous ½ cup of masa in the centre and a spoon of the reserved pork filling on top.", "Fold the long sides over the filling, fold both ends up, and tie with twine. Tie them in pairs so they are easy to count and to lift.", "Boil in salted water 1 hour, keeping them submerged. They are done when the masa pulls cleanly away from the husk.", "Hold hot in their husks at 135°F or above. Cut into 3 slices at service, in the husk."]', '["catering", "cuban", "needs_kitchen_review"]', 'draft', 1790078400000, 1790078400000, 'Tamales cubanos', 'Masa de maíz con cerdo, amarrada en hojas y hervida. Escrita para 45 tamales, que son 45 porciones de 3 rodajas.', '[{"item": "Masa harina para tamales (o 14 lb de maíz molido fresco)", "qty": "10 lb"}, {"item": "Masa de cerdo en cubitos", "qty": "6 lb"}, {"item": "Tocino de lomo en cubitos", "qty": "1 lb"}, {"item": "Cebolla amarilla en cubitos", "qty": "2 lb"}, {"item": "Ají verde en cubitos", "qty": "1½ lb"}, {"item": "Ajo picado", "qty": "½ taza"}, {"item": "Salsa de tomate", "qty": "1 cuarto de galón"}, {"item": "Comino molido", "qty": "2 cdas"}, {"item": "Orégano seco", "qty": "2 cdas"}, {"item": "Pimentón dulce", "qty": "2 cdas"}, {"item": "Vino blanco seco", "qty": "1 taza"}, {"item": "Caldo de cerdo o agua, tibio", "qty": "2½ galones"}, {"item": "Sal", "qty": "3 cdas"}, {"item": "Pimienta negra", "qty": "1 cda"}, {"item": "Hojas de maíz secas", "qty": "100 (calcule roturas)"}, {"item": "Hilo de cocina", "qty": "1 rollo"}]', '["Remoje las hojas en agua caliente al menos 30 minutos, hasta que doblen sin romperse.", "Sofría la tocineta, luego dore el cerdo en esa grasa por tandas. No llene la sartén.", "Agregue la cebolla y el ají; cocine hasta ablandar. Agregue el ajo, el comino, el orégano y el pimentón; cocine 1 minuto. Agregue el vino y después la salsa de tomate. Hierva a fuego lento 15 minutos. Aparte la mitad como relleno.", "Bata la masa harina en el caldo tibio hasta que quede suave y se pueda verter — como masa de panqueque. Incorpore el resto del sofrito, la sal y la pimienta.", "Ponga dos hojas superpuestas. Coloque ½ taza generosa de masa en el centro y una cucharada del relleno de cerdo encima.", "Doble los lados largos sobre el relleno, doble las dos puntas hacia arriba y amarre con hilo. Amárrelos en pares para contarlos y sacarlos con facilidad.", "Hierva en agua con sal 1 hora, manteniéndolos sumergidos. Están listos cuando la masa se despega limpia de la hoja.", "Mantenga calientes en su hoja a 135°F o más. Corte en 3 rodajas al servir, dentro de la hoja."]', '45 tamales (45 portions of 3 slices)', '45 tamales (45 porciones de 3 rodajas)');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es) VALUES ('rcp_cat_yuca', 'Yuca with onion & chicharrones', 'Boiled cassava under a hot garlic mojo, onions and crushed pork rind. Written for 45 portions of about 5 oz.', '[{"item": "Frozen yuca (cassava), peeled", "qty": "20 lb"}, {"item": "Water for boiling", "qty": "to cover"}, {"item": "Salt for the water", "qty": "½ cup"}, {"item": "Yellow onion, thin sliced", "qty": "4 lb"}, {"item": "Garlic, minced", "qty": "1 cup"}, {"item": "Olive oil", "qty": "3 cups"}, {"item": "Sour orange juice (or 2 parts orange to 1 part lime)", "qty": "3 cups"}, {"item": "Chicharrones, crushed", "qty": "2 lb"}, {"item": "Salt", "qty": "2 tbsp"}, {"item": "Black pepper", "qty": "1 tbsp"}]', '["Boil the yuca in well salted water 20 to 30 minutes, until a knife goes through with no resistance. Do not go further — overcooked yuca falls apart in the pan.", "Drain. Pull out the woody core from the middle of every piece; it is inedible and it is the thing guests notice.", "Cut into 2-inch pieces and put them in the service pan.", "For the mojo: heat the oil until it shimmers, add the garlic and cook just until it turns pale gold, about 40 seconds. It burns in seconds after that.", "Take the pan off the heat, stand back and add the sour orange — it will spit. Add the salt and pepper.", "Soften the onion in a little of the hot mojo, 3 to 4 minutes, so it is limp but still has bite.", "Pour the mojo over the yuca, lay the onions over the top, and hold at 135°F or above.", "Scatter the crushed chicharrones ON SERVICE, not before. They go soft in the pan within minutes."]', '["catering", "cuban", "needs_kitchen_review"]', 'draft', 1790078400000, 1790078400000, 'Yuca con cebolla y chicharrones', 'Yuca hervida bajo un mojo de ajo caliente, cebolla y chicharrón triturado. Escrita para 45 porciones de unas 5 oz.', '[{"item": "Yuca congelada, pelada", "qty": "20 lb"}, {"item": "Agua para hervir", "qty": "la necesaria"}, {"item": "Sal para el agua", "qty": "½ taza"}, {"item": "Cebolla amarilla en rodajas finas", "qty": "4 lb"}, {"item": "Ajo picado", "qty": "1 taza"}, {"item": "Aceite de oliva", "qty": "3 tazas"}, {"item": "Jugo de naranja agria (o 2 partes de naranja por 1 de limón)", "qty": "3 tazas"}, {"item": "Chicharrones triturados", "qty": "2 lb"}, {"item": "Sal", "qty": "2 cdas"}, {"item": "Pimienta negra", "qty": "1 cda"}]', '["Hierva la yuca en agua con bastante sal de 20 a 30 minutos, hasta que el cuchillo entre sin resistencia. No más — la yuca pasada se deshace en la bandeja.", "Escurra. Saque la fibra dura del centro de cada pedazo; no se come y es lo que el invitado nota.", "Corte en trozos de 2 pulgadas y colóquelos en la bandeja de servicio.", "Para el mojo: caliente el aceite hasta que brille, agregue el ajo y cocine solo hasta que tome color dorado claro, unos 40 segundos. Después de eso se quema en segundos.", "Retire del fuego, hágase a un lado y agregue la naranja agria — va a saltar. Agregue la sal y la pimienta.", "Ablande la cebolla en un poco del mojo caliente, de 3 a 4 minutos, para que quede blanda pero con textura.", "Vierta el mojo sobre la yuca, acomode la cebolla encima y mantenga a 135°F o más.", "Esparza los chicharrones AL SERVIR, no antes. En la bandeja se ablandan en minutos."]', '45 portions of about 5 oz', '45 porciones de unas 5 oz');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es) VALUES ('rcp_cat_croq_sausage', 'Sausage croquetas', 'A stiff béchamel bound with sausage, chilled hard, breaded and fried. Written for 45 croquetas at 1.20 oz fried.', '[{"item": "Cooked sausage, finely ground", "qty": "2 lb"}, {"item": "Butter", "qty": "6 oz"}, {"item": "All-purpose flour", "qty": "6 oz"}, {"item": "Whole milk", "qty": "3 cups"}, {"item": "Yellow onion, minced fine", "qty": "6 oz"}, {"item": "Garlic, minced", "qty": "2 tbsp"}, {"item": "Grated nutmeg", "qty": "½ tsp"}, {"item": "Salt", "qty": "1 tbsp"}, {"item": "White pepper", "qty": "1 tsp"}, {"item": "Eggs, beaten", "qty": "6"}, {"item": "Fine dry breadcrumbs", "qty": "2 lb"}, {"item": "All-purpose flour for dusting", "qty": "1 lb"}, {"item": "Frying oil", "qty": "1 gal"}]', '["Sweat the onion in the butter over medium heat until translucent, about 5 minutes. Add the garlic for 1 minute.", "Add the flour and cook it, stirring constantly, 3 to 4 minutes. It must lose the raw flour smell or the croquetas taste pasty.", "Add the milk a little at a time, beating smooth after each addition. Cook until it is thick enough that the spoon leaves a track across the bottom of the pan.", "Beat in the sausage, nutmeg, salt and pepper. Cook 2 more minutes.", "Spread it 1 inch deep in an oiled sheet pan, press film to the surface, and CHILL AT LEAST 4 HOURS — overnight is better. Warm mixture cannot be rolled and bursts in the fryer.", "Portion at 1.2 oz and roll into cylinders. Flour, then egg, then breadcrumb. Bread them twice for an event: a single coat splits.", "Chill the breaded croquetas again, at least 30 minutes.", "Fry at 350°F, 8 to 10 at a time, 2 to 3 minutes until deep gold. Any more at once drops the oil temperature and they soak.", "Drain on a rack, never on paper in a stack. Hold at 135°F or above, uncovered, or they steam soft."]', '["catering", "cuban", "needs_kitchen_review"]', 'draft', 1790078400000, 1790078400000, 'Croquetas de salchicha', 'Bechamel espesa ligada con salchicha, bien fría, empanada y frita. Escrita para 45 croquetas de 1.20 oz fritas.', '[{"item": "Salchicha cocida, molida fina", "qty": "2 lb"}, {"item": "Mantequilla", "qty": "6 oz"}, {"item": "Harina de trigo", "qty": "6 oz"}, {"item": "Leche entera", "qty": "3 tazas"}, {"item": "Cebolla amarilla picada fina", "qty": "6 oz"}, {"item": "Ajo picado", "qty": "2 cdas"}, {"item": "Nuez moscada rallada", "qty": "½ cdta"}, {"item": "Sal", "qty": "1 cda"}, {"item": "Pimienta blanca", "qty": "1 cdta"}, {"item": "Huevos batidos", "qty": "6"}, {"item": "Pan rallado fino", "qty": "2 lb"}, {"item": "Harina para enharinar", "qty": "1 lb"}, {"item": "Aceite para freír", "qty": "1 galón"}]', '["Sude la cebolla en la mantequilla a fuego medio hasta que esté transparente, unos 5 minutos. Agregue el ajo 1 minuto.", "Agregue la harina y cocínela, revolviendo sin parar, de 3 a 4 minutos. Tiene que perder el olor a harina cruda o la croqueta sabe a engrudo.", "Agregue la leche poco a poco, batiendo hasta alisar cada vez. Cocine hasta que espese tanto que la cuchara deje surco en el fondo.", "Incorpore la salchicha, la nuez moscada, la sal y la pimienta. Cocine 2 minutos más.", "Extienda en una bandeja aceitada con 1 pulgada de grosor, cubra con plástico pegado a la superficie y ENFRÍE AL MENOS 4 HORAS — mejor toda la noche. La mezcla tibia no se puede rodar y revienta en el aceite.", "Porcione a 1.2 oz y forme cilindros. Harina, huevo y pan rallado. Para un evento empánelas dos veces: una sola capa se abre.", "Vuelva a enfriar las croquetas empanadas, al menos 30 minutos.", "Fría a 350°F, de 8 a 10 a la vez, de 2 a 3 minutos hasta dorado oscuro. Más a la vez baja la temperatura del aceite y se empapan.", "Escurra sobre rejilla, nunca sobre papel y amontonadas. Mantenga a 135°F o más, destapadas, o el vapor las ablanda."]', '45 croquetas at 1.20 oz fried', '45 croquetas de 1.20 oz fritas');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es) VALUES ('rcp_cat_macaroni', 'Cold macaroni salad', 'The cold side, dressed twice so it is not dry by service. Written for 45 portions of 6 oz.', '[{"item": "Elbow macaroni, dry", "qty": "5 lb"}, {"item": "Mayonnaise", "qty": "2 qt"}, {"item": "Yellow mustard", "qty": "¾ cup"}, {"item": "White vinegar", "qty": "½ cup"}, {"item": "Sweet pickle relish", "qty": "2 cups"}, {"item": "Yellow onion, fine dice", "qty": "1 lb"}, {"item": "Celery, fine dice", "qty": "1 lb"}, {"item": "Red bell pepper, fine dice", "qty": "1 lb"}, {"item": "Cooked ham, small dice", "qty": "1½ lb"}, {"item": "Hard-boiled eggs, chopped", "qty": "12"}, {"item": "Sugar", "qty": "3 tbsp"}, {"item": "Salt", "qty": "2 tbsp"}, {"item": "Black pepper", "qty": "1 tbsp"}, {"item": "Paprika, to finish", "qty": "1 tbsp"}]', '["Boil the macaroni in salted water to just past al dente — it firms up cold, and undercooked pasta stays hard in a cold salad.", "Drain and rinse under cold water until the pasta is cold all the way through. Drain it WELL; water left in the pan thins the dressing.", "Whisk the mayonnaise, mustard, vinegar, sugar, salt and pepper into a dressing.", "Fold two thirds of the dressing through the pasta while it is still slightly damp. Refrigerate at least 2 hours.", "Before service, fold in the onion, celery, pepper, ham, relish and egg, then the last third of the dressing. Pasta drinks dressing as it sits — this second pass is what keeps it from arriving dry.", "Taste and correct the salt. Dust with paprika.", "Hold at 41°F or below, in a cold pan set over ice, never on the same table as the hot pans."]', '["catering", "cuban", "needs_kitchen_review"]', 'draft', 1790078400000, 1790078400000, 'Ensalada fría de coditos', 'La guarnición fría, aliñada dos veces para que no llegue seca al servicio. Escrita para 45 porciones de 6 oz.', '[{"item": "Coditos secos", "qty": "5 lb"}, {"item": "Mayonesa", "qty": "2 cuartos de galón"}, {"item": "Mostaza amarilla", "qty": "¾ taza"}, {"item": "Vinagre blanco", "qty": "½ taza"}, {"item": "Relish de pepino dulce", "qty": "2 tazas"}, {"item": "Cebolla amarilla picada fina", "qty": "1 lb"}, {"item": "Apio picado fino", "qty": "1 lb"}, {"item": "Ají rojo picado fino", "qty": "1 lb"}, {"item": "Jamón cocido en cubitos", "qty": "1½ lb"}, {"item": "Huevos duros picados", "qty": "12"}, {"item": "Azúcar", "qty": "3 cdas"}, {"item": "Sal", "qty": "2 cdas"}, {"item": "Pimienta negra", "qty": "1 cda"}, {"item": "Pimentón para terminar", "qty": "1 cda"}]', '["Hierva los coditos en agua con sal justo pasado el punto al dente — endurecen en frío, y la pasta cruda se queda dura en ensalada fría.", "Escurra y enjuague con agua fría hasta que la pasta esté fría por dentro. Escurra BIEN; el agua que queda aguada el aliño.", "Bata la mayonesa, la mostaza, el vinagre, el azúcar, la sal y la pimienta hasta formar el aliño.", "Mezcle dos tercios del aliño con la pasta todavía algo húmeda. Refrigere al menos 2 horas.", "Antes de servir, incorpore la cebolla, el apio, el ají, el jamón, el relish y el huevo, y después el último tercio del aliño. La pasta se bebe el aliño mientras reposa — esta segunda pasada es lo que evita que llegue seca.", "Pruebe y corrija la sal. Espolvoree con pimentón.", "Mantenga a 41°F o menos, en bandeja fría sobre hielo, nunca en la misma mesa que las bandejas calientes."]', '45 portions of 6 oz', '45 porciones de 6 oz');
INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es) VALUES ('rcp_cat_skewers', 'Skewers — grape, ham, cheese, guava & pineapple', 'Assembly only, no cooking. Written for 45 skewers, one of each item per skewer.', '[{"item": "Bamboo skewers, 6 inch", "qty": "50 (allow for breakage)"}, {"item": "Seedless red grapes", "qty": "3 lb"}, {"item": "Deli ham, thin sliced", "qty": "2 lb"}, {"item": "Firm white cheese or Edam, ½-inch cubes", "qty": "3 lb"}, {"item": "Guava paste, ½-inch cubes", "qty": "2 lb"}, {"item": "Fresh pineapple, ½-inch cubes", "qty": "3 lb"}]', '["Cut the cheese, guava and pineapple into ½-inch cubes of the same size, so the finished skewers line up on the platter.", "Pat the pineapple dry. Wet fruit makes the guava sticky and the ham slide.", "Fold each slice of ham into a small ribbon, in quarters — it holds on the stick and it is what stops the skewer looking flat.", "Thread in this order: grape, ham, cheese, guava, pineapple. Keep the order the same on every skewer; the platter is the product.", "Lay them in one layer on a lined tray, cover, and hold at 41°F or below.", "Build these NO MORE THAN 4 HOURS before service. The guava weeps and stains the cheese after that.", "Arrange on the platter at the venue, not in the kitchen. They shift on the drive."]', '["catering", "cuban", "needs_kitchen_review"]', 'draft', 1790078400000, 1790078400000, 'Pinchos — uva, jamón, queso, guayaba y piña', 'Solo montaje, no se cocina. Escrita para 45 pinchos, uno de cada cosa por pincho.', '[{"item": "Palillos de bambú de 6 pulgadas", "qty": "50 (calcule roturas)"}, {"item": "Uvas rojas sin semilla", "qty": "3 lb"}, {"item": "Jamón de sándwich en lonjas finas", "qty": "2 lb"}, {"item": "Queso blanco firme o Edam en cubos de ½ pulgada", "qty": "3 lb"}, {"item": "Pasta de guayaba en cubos de ½ pulgada", "qty": "2 lb"}, {"item": "Piña fresca en cubos de ½ pulgada", "qty": "3 lb"}]', '["Corte el queso, la guayaba y la piña en cubos de ½ pulgada del mismo tamaño, para que los pinchos queden parejos en la bandeja.", "Seque la piña con papel. La fruta mojada pone pegajosa la guayaba y hace resbalar el jamón.", "Doble cada lonja de jamón en cuatro, como una cinta pequeña — se sostiene en el palillo y es lo que evita que el pincho se vea plano.", "Ensarte en este orden: uva, jamón, queso, guayaba, piña. Mantenga el mismo orden en todos; la bandeja es el producto.", "Acomódelos en una sola capa sobre bandeja forrada, tape y mantenga a 41°F o menos.", "Ármelos NO MÁS DE 4 HORAS antes del servicio. Después de eso la guayaba suda y mancha el queso.", "Acomode la bandeja en el lugar del evento, no en la cocina. Se mueven en el viaje."]', '45 skewers, 1 piece each', '45 pinchos, 1 pieza cada uno');
